<script setup lang="ts">
import { ref, reactive, useTemplateRef, watch } from 'vue';
import {
    ElTable,
    ElTableColumn,
    ElInput,
    ElSpace,
    ElButton,
    ElPagination,
} from 'element-plus';
import type { TableInstance } from 'element-plus';
import { Search } from '@element-plus/icons-vue';

import { Item } from '@/stores/bom';
import useSettingStore from '@/stores/settings';
import { RecipeInfo } from '@/libs/Craft';

const emits = defineEmits<{
    clickItem: [item: Item];
    selectItems: [items: Item[]];
}>();

const settingStore = useSettingStore();

const search = ref('');
const recipeList = ref<RecipeInfo[]>([]);
const isLoading = ref(false);
const tableInstance = useTemplateRef<TableInstance>('table');

const pagination = reactive({
    page: 1,
    totalPages: 1,
});

async function update() {
    try {
        isLoading.value = true;
        const source = await settingStore.getDataSource();
        const recipeTable = await source.recipeTable(
            pagination.page,
            search.value,
        );
        recipeList.value = recipeTable.results;
        pagination.totalPages = recipeTable.totalPages;
    } finally {
        isLoading.value = false;
    }
}

watch(
    search,
    () => {
        pagination.page = 1;
        update();
    },
    { immediate: true },
);

function handlePageChange(page: number) {
    pagination.page = page;
    update();
}

const selected = ref<RecipeInfo[]>([]);
function selectionChanged(rows: RecipeInfo[]) {
    selected.value = rows;
}
function selectionConfirmed() {
    const items = selected.value.map(v => ({
        id: v.item_id,
        name: v.item_name,
    }));
    emits('selectItems', items);
    clearSelections();
}

async function selectItem(recipe: RecipeInfo) {
    emits('clickItem', { id: recipe.item_id, name: recipe.item_name });
    clearSelections();
}

function clearSelections() {
    selected.value.splice(0);
    tableInstance.value!.clearSelection();
}
</script>

<template>
    <el-table
        ref="table"
        :data="recipeList"
        @row-click="selectItem"
        max-height="300"
        v-tnze-loading="isLoading"
        @selection-change="selectionChanged"
    >
        <el-table-column type="selection" width="55" />
        <el-table-column prop="job" :label="$t('craft-type')" width="150" />
        <el-table-column prop="item_name" :label="$t('name')">
            <template #header>
                <el-space>
                    <span>{{ $t('name') }}</span>
                    <el-input
                        v-model="search"
                        size="small"
                        :placeholder="$t('type-to-search')"
                        :prefix-icon="Search"
                        style="width: 200px"
                    />
                </el-space>
            </template>
        </el-table-column>
    </el-table>
    <div class="pagination-wrapper">
        <el-pagination
            v-model:current-page="pagination.page"
            :page-count="pagination.totalPages"
            :pager-count="5"
            layout="prev, pager, next"
            size="small"
            background
            @current-change="handlePageChange"
        />
    </div>
    <div class="buttons" v-if="selected.length > 0">
        <el-button type="primary" @click="selectionConfirmed">
            {{ $t('confirm') }}
        </el-button>
    </div>
</template>

